import { test, expect } from '@playwright/test';

test.describe('Async State Preservation During Browser Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/async-state');
  });

  test('should preserve async state when navigating back and forth', async ({ page }) => {
    // Verify initial async state is loaded
    const asyncValue = page.getByTestId('async-value');
    await expect(asyncValue).toContainText('Loaded');

    // Trigger async operation
    const asyncButton = page.getByRole('button', { name: /start async/i });
    await asyncButton.click();

    // Wait for async operation to complete
    await page.waitForResponse(response => 
      response.url().includes('/api/async-operation') && response.status() === 200
    );

    // Verify async state is updated
    await expect(asyncValue).toContainText('Completed');
    const statusIndicator = page.getByTestId('status-indicator');
    await expect(statusIndicator).toHaveText('Success');

    // Navigate to another page
    const navLink = page.getByRole('link', { name: /dashboard/i });
    await navLink.click();

    // Navigate back to the async state page
    await page.goto('/async-state');

    // Verify async state is preserved after navigation
    await expect(asyncValue).toContainText('Completed');
    await expect(statusIndicator).toHaveText('Success');

    // Verify async button is still available
    const asyncButtonAfterNav = page.getByRole('button', { name: /start async/i });
    await expect(asyncButtonAfterNav).toBeVisible();
  });

  test('should handle async state reset when navigating to a new session', async ({ page }) => {
    // Verify initial async state is loaded
    const asyncValue = page.getByTestId('async-value');
    await expect(asyncValue).toContainText('Loaded');

    // Trigger async operation
    const asyncButton = page.getByRole('button', { name: /start async/i });
    await asyncButton.click();

    // Wait for async operation to complete
    await page.waitForResponse(response => 
      response.url().includes('/api/async-operation') && response.status() === 200
    );

    // Verify async state is updated
    await expect(asyncValue).toContainText('Completed');
    const statusIndicator = page.getByTestId('status-indicator');
    await expect(statusIndicator).toHaveText('Success');

    // Navigate to a different page
    const navLink = page.getByRole('link', { name: /settings/i });
    await navLink.click();

    // Navigate back to async state page
    await page.goto('/async-state');

    // Verify async state is preserved
    await expect(asyncValue).toContainText('Completed');
    await expect(statusIndicator).toHaveText('Success');

    // Navigate to a completely different section
    const homeLink = page.getByRole('link', { name: /home/i });
    await homeLink.click();

    // Navigate back to async state page
    await page.goto('/async-state');

    // Verify async state is still preserved
    await expect(asyncValue).toContainText('Completed');
    await expect(statusIndicator).toHaveText('Success');
  });
});
